insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('siep-badge-art','siep-badge-art',false,5242880,array['image/png','image/jpeg']) on conflict(id) do nothing;
do $$ begin if exists(select 1 from storage.buckets where id='siep-badge-art' and public) then raise exception 'Arte do crachá precisa de bucket privado';end if;end $$;
create table public.badge_art_assets(id uuid primary key default gen_random_uuid(),institution_id uuid not null,event_id uuid not null,object_path text not null unique,original_name text not null,mime_type text not null check(mime_type in ('image/png','image/jpeg')),size_bytes integer not null check(size_bytes between 1 and 5242880),status text not null default 'pending' check(status in ('pending','uploaded')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(institution_id,event_id) references public.events(institution_id,id));
create table public.badge_templates(id uuid primary key default gen_random_uuid(),institution_id uuid not null,event_id uuid not null,role text not null check(role in ('athlete','staff','responsible')),version integer not null check(version>0),layout jsonb not null,background_id uuid references public.badge_art_assets(id),updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),unique(event_id,role),foreign key(institution_id,event_id) references public.events(institution_id,id));
create table public.badge_template_versions(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.badge_templates(id),institution_id uuid not null,event_id uuid not null,role text not null,version integer not null,layout jsonb not null,background_id uuid references public.badge_art_assets(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(template_id,version),foreign key(institution_id,event_id) references public.events(institution_id,id));
alter table public.badge_template_versions enable row level security;
revoke all on public.badge_template_versions from public,anon,authenticated;grant select on public.badge_template_versions to authenticated;
create policy badge_template_versions_read on public.badge_template_versions for select to authenticated using(siep_private.is_staff(institution_id));
create function siep_private.badge_template_version_immutable() returns trigger language plpgsql set search_path=pg_catalog as $$begin raise exception 'Versão do modelo é imutável' using errcode='23514';end $$;
create trigger badge_template_version_immutable before update or delete on public.badge_template_versions for each row execute function siep_private.badge_template_version_immutable();
alter table public.event_badges add column template_version_id uuid references public.badge_template_versions(id);
create function siep_private.badge_template_reference_immutable() returns trigger language plpgsql set search_path=pg_catalog as $$begin if new.template_version_id is distinct from old.template_version_id then raise exception 'Modelo da emissão é imutável' using errcode='23514';end if;return new;end $$;
create trigger badge_template_reference_immutable before update on public.event_badges for each row execute function siep_private.badge_template_reference_immutable();
revoke all on function siep_private.badge_template_version_immutable(),siep_private.badge_template_reference_immutable() from public,anon,authenticated;
alter table public.badge_art_assets enable row level security;alter table public.badge_templates enable row level security;
revoke all on public.badge_art_assets,public.badge_templates from public,anon,authenticated;grant select on public.badge_art_assets,public.badge_templates to authenticated;
create policy badge_art_read on public.badge_art_assets for select to authenticated using(siep_private.is_staff(institution_id));
create policy badge_templates_read on public.badge_templates for select to authenticated using(siep_private.is_staff(institution_id));
create function siep_private.badge_art_access(path text,upload boolean) returns boolean language sql stable security definer set search_path=pg_catalog as $$select exists(select 1 from public.badge_art_assets a where a.object_path=path and siep_private.is_staff(a.institution_id) and case when upload then a.status='pending' and a.created_by=auth.uid() else a.status='uploaded' end);$$;
revoke all on function siep_private.badge_art_access(text,boolean) from public,anon;grant execute on function siep_private.badge_art_access(text,boolean) to authenticated;
create policy badge_art_storage_read on storage.objects for select to authenticated using(bucket_id='siep-badge-art' and siep_private.badge_art_access(name,false));
create policy badge_art_storage_insert on storage.objects for insert to authenticated with check(bucket_id='siep-badge-art' and owner_id=auth.uid()::text and siep_private.badge_art_access(name,true));
create function public.siep_prepare_badge_art(p_event_id uuid,p_name text,p_mime_type text,p_size_bytes integer) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare tenant uuid;art_uuid uuid:=gen_random_uuid();path text;begin select institution_id into tenant from public.events where id=p_event_id;perform siep_private.require_staff(tenant);if p_mime_type is null or p_mime_type not in ('image/png','image/jpeg') or p_size_bytes is null or p_size_bytes not between 1 and 5242880 or length(btrim(coalesce(p_name,''))) not between 1 and 255 then raise exception 'Use arte PNG ou JPEG de até 5 MB' using errcode='23514';end if;path:=tenant||'/'||p_event_id||'/'||art_uuid||case p_mime_type when 'image/png' then '.png' else '.jpg' end;insert into public.badge_art_assets(id,institution_id,event_id,object_path,original_name,mime_type,size_bytes,created_by) values(art_uuid,tenant,p_event_id,path,btrim(p_name),p_mime_type,p_size_bytes,auth.uid());return jsonb_build_object('id',art_uuid,'bucket','siep-badge-art','path',path);end $$;
create function public.siep_finalize_badge_art(p_art_id uuid) returns void language plpgsql security definer set search_path=pg_catalog as $$declare a public.badge_art_assets;m jsonb;begin select * into a from public.badge_art_assets where id=p_art_id;perform siep_private.require_staff(a.institution_id);if a.status<>'pending' or a.created_by<>auth.uid() then raise exception 'Arte indisponível' using errcode='42501';end if;select metadata into m from storage.objects where bucket_id='siep-badge-art' and name=a.object_path;if m is null or coalesce(m->>'size','') !~ '^[0-9]+$' or (m->>'size')::bigint<>a.size_bytes or m->>'mimetype' is distinct from a.mime_type then raise exception 'Upload da arte não foi confirmado' using errcode='23514';end if;update public.badge_art_assets set status='uploaded' where id=a.id;end $$;
create function siep_private.validate_badge_layout(p_role text,p_layout jsonb) returns void language plpgsql set search_path=pg_catalog as $$declare f jsonb;k text;seen text[]:='{}';required text[]:=array['photo','person_name','school_name'];begin
 if p_role is null or p_role not in ('athlete','staff','responsible') or jsonb_typeof(p_layout)<>'object' or p_layout->>'width' is distinct from '86' or p_layout->>'height' is distinct from '130' or coalesce(p_layout->>'fit','') not in ('contain','cover') or jsonb_typeof(p_layout->'fields') is distinct from 'array' or jsonb_array_length(p_layout->'fields') not between 4 and 12 or octet_length(p_layout::text)>16384 or p_layout-array['width','height','fit','fields']<>'{}' then raise exception 'Modelo de crachá inválido' using errcode='23514';end if;
 required:=required||case p_role when 'athlete' then 'modalities' when 'staff' then 'functions' else 'role_label' end;
 for f in select value from jsonb_array_elements(p_layout->'fields') loop
  k:=f->>'key';if jsonb_typeof(f)<>'object' or k is null or k not in ('photo','person_name','school_name','role_label','event_name','edition','modalities','categories','proofs','functions','code') or k=any(seen) or (p_role='athlete' and k='functions') or (p_role='staff' and k='proofs') or (p_role='responsible' and k in ('modalities','categories','proofs')) or f-array['key','x','y','w','h','fontSize','color','align']<>'{}' then raise exception 'Campo inválido para este perfil' using errcode='23514';end if;
  seen:=array_append(seen,k);
  if jsonb_typeof(f->'x') is distinct from 'number' or jsonb_typeof(f->'y') is distinct from 'number' or jsonb_typeof(f->'w') is distinct from 'number' or jsonb_typeof(f->'h') is distinct from 'number' or jsonb_typeof(f->'fontSize') is distinct from 'number' then raise exception 'Medidas inválidas' using errcode='23514';end if;
  if (f->>'x')::numeric<0 or (f->>'y')::numeric<0 or (f->>'w')::numeric<2 or (f->>'h')::numeric<2 or (f->>'x')::numeric+(f->>'w')::numeric>100 or (f->>'y')::numeric+(f->>'h')::numeric>100 or (f->>'fontSize')::numeric not between 6 and 28 or coalesce(f->>'color','') !~* '^#[0-9a-f]{6}$' or coalesce(f->>'align','') not in ('left','center','right') then raise exception 'Campos precisam caber no crachá' using errcode='23514';end if;
 end loop;if not required<@seen then raise exception 'Mantenha nome, foto, escola e campo obrigatório do perfil' using errcode='23514';end if;
end $$;
create function siep_private.badge_template_version_snapshot(p_version_id uuid) returns jsonb language sql stable security definer set search_path=pg_catalog as $$select jsonb_build_object('id',v.template_id,'version_id',v.id,'version',v.version,'role',v.role,'layout',v.layout,'background',case when a.id is null then null else jsonb_build_object('id',a.id,'bucket','siep-badge-art','objectPath',a.object_path,'name',a.original_name) end) from public.badge_template_versions v left join public.badge_art_assets a on a.id=v.background_id and a.status='uploaded' where v.id=p_version_id;$$;
create function siep_private.badge_template_snapshot(ev uuid,profile text) returns jsonb language sql stable security definer set search_path=pg_catalog as $$select siep_private.badge_template_version_snapshot(v.id) from public.badge_templates t join public.badge_template_versions v on v.template_id=t.id and v.version=t.version where t.event_id=ev and t.role=profile;$$;
create function public.siep_badge_template(p_event_id uuid,p_role text) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare tenant uuid;begin select institution_id into tenant from public.events where id=p_event_id;perform siep_private.require_staff(tenant);return siep_private.badge_template_snapshot(p_event_id,p_role);end $$;
create function public.siep_save_badge_template(p_event_id uuid,p_role text,p_expected_version integer,p_layout jsonb,p_background_id uuid default null) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare tenant uuid;t public.badge_templates;begin select institution_id into tenant from public.events where id=p_event_id for update;perform siep_private.require_staff(tenant);perform siep_private.validate_badge_layout(p_role,p_layout);select * into t from public.badge_templates where event_id=p_event_id and role=p_role for update;if p_expected_version is distinct from coalesce(t.version,0) then raise exception 'Modelo alterado; recarregue antes de salvar' using errcode='40001';end if;if p_background_id is not null and not exists(select 1 from public.badge_art_assets where id=p_background_id and institution_id=tenant and event_id=p_event_id and status='uploaded') then raise exception 'Arte não pertence a este evento ou não foi confirmada' using errcode='23514';end if;insert into public.badge_templates(institution_id,event_id,role,version,layout,background_id,updated_by) values(tenant,p_event_id,p_role,1,p_layout,p_background_id,auth.uid()) on conflict(event_id,role) do update set version=badge_templates.version+1,layout=excluded.layout,background_id=excluded.background_id,updated_by=auth.uid(),updated_at=now() returning * into t;insert into public.badge_template_versions(template_id,institution_id,event_id,role,version,layout,background_id,created_by) values(t.id,t.institution_id,t.event_id,t.role,t.version,t.layout,t.background_id,auth.uid());return siep_private.badge_template_snapshot(p_event_id,p_role);end $$;
create function siep_private.badge_dynamic_data(ev uuid,school uuid,person uuid,profile text) returns jsonb language sql stable set search_path=pg_catalog as $$
 with involved as(select r.* from public.registrations r where r.event_id=ev and r.school_id=school and r.status='approved' and case when profile='athlete' then exists(select 1 from public.registration_athletes a where a.registration_id=r.id and a.person_id=person and a.active) when profile='staff' then exists(select 1 from public.registration_staff a where a.registration_id=r.id and a.person_id=person) else false end)
 select jsonb_build_object('modalities',(select string_agg(distinct m.name,' / ' order by m.name) from involved r join public.event_categories c on c.id=r.category_id join public.event_modalities m on m.id=c.modality_id),'categories',(select string_agg(distinct c.name,' / ' order by c.name) from involved r join public.event_categories c on c.id=r.category_id),'proofs',(select string_agg(distinct p.name,' / ' order by p.name) from involved r join public.event_proofs p on p.id=r.proof_id),'functions',case when profile='responsible' then coalesce((select nullif(sp.position,'') from public.school_people sp where sp.school_id=school and sp.person_id=person and sp.role='responsible'),'Responsável escolar') else (select string_agg(distinct f.name,' / ' order by f.name) from involved r join public.registration_staff a on a.registration_id=r.id and a.person_id=person join public.event_staff_roles f on f.id=a.staff_role_id) end);
$$;
revoke all on function siep_private.badge_template_version_snapshot(uuid),siep_private.validate_badge_layout(text,jsonb),siep_private.badge_template_snapshot(uuid,text),siep_private.badge_dynamic_data(uuid,uuid,uuid,text) from public,anon,authenticated;
revoke all on function public.siep_prepare_badge_art(uuid,text,text,integer),public.siep_finalize_badge_art(uuid),public.siep_badge_template(uuid,text),public.siep_save_badge_template(uuid,text,integer,jsonb,uuid) from public,anon;
grant execute on function public.siep_prepare_badge_art(uuid,text,text,integer),public.siep_finalize_badge_art(uuid),public.siep_badge_template(uuid,text),public.siep_save_badge_template(uuid,text,integer,jsonb,uuid) to authenticated;

create or replace function public.siep_issue_event_badges(p_event_id uuid,p_entries jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog as $$
declare event public.events;institution public.institutions;entry jsonb;candidate jsonb;candidates jsonb;result jsonb:='[]';badge public.event_badges;next_version integer;person_uuid uuid;school_uuid uuid;badge_role text;seen text[]:=array[]::text[];key text;template jsonb;
begin
 select * into event from public.events where id=p_event_id for update;
 if not found then raise exception 'Evento indisponível' using errcode='P0002';end if;
 perform siep_private.require_staff(event.institution_id);
 if event.status='archived' then raise exception 'Evento arquivado não recebe novas emissões' using errcode='23514';end if;
 if jsonb_typeof(p_entries) is distinct from 'array' then raise exception 'Selecione as pessoas para emitir' using errcode='23514';end if;
 if jsonb_array_length(p_entries) not between 1 and 50 then raise exception 'Emita de 1 a 50 crachás por lote' using errcode='23514';end if;
 select * into institution from public.institutions where id=event.institution_id;
 select coalesce(jsonb_agg(to_jsonb(c)),'[]') into candidates from siep_private.badge_rows(event.id,null,null,'') c where exists(select 1 from jsonb_array_elements(p_entries) e where e->>'person_id'=c.person_id::text and e->>'school_id'=c.school_id::text and e->>'role'=c.role);
 for entry in select value from jsonb_array_elements(p_entries) loop
  person_uuid:=(entry->>'person_id')::uuid;school_uuid:=(entry->>'school_id')::uuid;badge_role:=entry->>'role';
  key:=coalesce(person_uuid::text,'')||':'||coalesce(school_uuid::text,'')||':'||coalesce(badge_role,'');
  if key=any(seen) then raise exception 'Não repita uma pessoa/papel no lote' using errcode='23514';end if;
  seen:=array_append(seen,key);
  select value into candidate from jsonb_array_elements(candidates) where value->>'person_id'=person_uuid::text and value->>'school_id'=school_uuid::text and value->>'role'=badge_role;
  if candidate is null then raise exception 'Pessoa sem vínculo e inscrição aprovados neste evento' using errcode='23514';end if;
  if candidate->>'photo_id' is null then raise exception 'Complete a foto de identificação antes de emitir o crachá' using errcode='23514';end if;
  template:=siep_private.badge_template_snapshot(event.id,badge_role);
  candidate:=candidate||siep_private.badge_dynamic_data(event.id,school_uuid,person_uuid,badge_role)||jsonb_build_object('badge_template',case when template is null then null else jsonb_build_object('id',template->'id','version_id',template->'version_id','version',template->'version') end);
  select coalesce(max(version),0)+1 into next_version from public.event_badges where event_id=event.id and school_id=school_uuid and person_id=person_uuid and role=badge_role;
  update public.event_badges set is_current=false where event_id=event.id and school_id=school_uuid and person_id=person_uuid and role=badge_role and is_current;
  insert into public.event_badges(institution_id,event_id,school_id,person_id,role,photo_id,version,snapshot,issued_by,template_version_id)
  values(event.institution_id,event.id,school_uuid,person_uuid,badge_role,(candidate->>'photo_id')::uuid,next_version,candidate||jsonb_build_object('event_name',event.name,'edition',event.edition,'institution_name',institution.name,'event_id',event.id),auth.uid(),(template->>'version_id')::uuid) returning * into badge;
  result:=result||jsonb_build_array(to_jsonb(badge)||jsonb_build_object('snapshot',badge.snapshot||jsonb_build_object('badge_template',template)));
 end loop;
 return result;
end $$;

notify pgrst,'reload schema';

create function public.siep_badge_history(p_institution_id uuid,p_event_id uuid,p_school_id uuid default null) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare result jsonb;begin perform siep_private.require_staff(p_institution_id);if not exists(select 1 from public.events where institution_id=p_institution_id and id=p_event_id) then raise exception 'Evento indisponível' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('snapshot',b.snapshot||jsonb_build_object('badge_template',siep_private.badge_template_version_snapshot(b.template_version_id))) order by b.issued_at desc,b.id),'[]') into result from (select * from public.event_badges where institution_id=p_institution_id and event_id=p_event_id and (p_school_id is null or school_id=p_school_id) order by issued_at desc,id limit 100) b;return result;end $$;
revoke all on function public.siep_badge_history(uuid,uuid,uuid) from public,anon;grant execute on function public.siep_badge_history(uuid,uuid,uuid) to authenticated;
notify pgrst,'reload schema';
